"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """One aligned row per student, sorted by name."""
    ordered = _by_name(students)
    _require_emails(ordered)
    names = [item.display_name for item in ordered]
    sections = [item.section for item in ordered]
    widths = (max(map(len, names)), max(map(len, sections)))
    return [_row(item, widths) for item in ordered]

def _by_name(students: Iterable[Student]) -> List[Student]:
    return sorted(
        students, key=lambda item: item.display_name
    )

def _require_emails(ordered: List[Student]) -> None:
    if not ordered:
        raise ValueError("no students given")
    for item in ordered:
        if not item.email:
            message = f"no email for {item.display_name}"
            raise ValueError(message)

def _row(student: Student, widths: Tuple[int, int]) -> str:
    name_width, section_width = widths
    name = student.display_name.ljust(name_width)
    section = student.section.ljust(section_width)
    return f"{name}  {section}  {student.email}"
